CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,email text,display_name text,avatar_url text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users manage own profile" ON public.profiles FOR ALL USING(auth.uid()=id) WITH CHECK(auth.uid()=id);
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role public.app_role NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,role)); GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users read own roles" ON public.user_roles FOR SELECT USING(auth.uid()=user_id);
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role)$$; REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE TABLE public.prompts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,name text NOT NULL,content text NOT NULL,category text NOT NULL DEFAULT 'global' CHECK(category IN('global','message','comment','md','tutorial','post')),is_active boolean NOT NULL DEFAULT true,page_id text,assistance_type text,page_ids text[] NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.prompts TO authenticated; GRANT ALL ON public.prompts TO service_role; ALTER TABLE public.prompts ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users manage own prompts" ON public.prompts FOR ALL USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id); CREATE INDEX prompts_user_page_idx ON public.prompts(user_id,page_id); CREATE INDEX prompts_user_type_idx ON public.prompts(user_id,assistance_type); CREATE INDEX idx_prompts_page_ids ON public.prompts USING gin(page_ids);
CREATE TABLE public.gemini_keys(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,label text NOT NULL,api_key text NOT NULL,is_active boolean NOT NULL DEFAULT true,last_used_at timestamptz,error_count int NOT NULL DEFAULT 0,disabled_until timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.gemini_keys TO authenticated; GRANT ALL ON public.gemini_keys TO service_role; ALTER TABLE public.gemini_keys ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users manage own gemini keys" ON public.gemini_keys FOR ALL USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.facebook_pages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,page_id text NOT NULL,page_name text NOT NULL,page_access_token text NOT NULL,user_access_token text,token_expires_at timestamptz,is_connected boolean NOT NULL DEFAULT true,webhook_subscribed boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,page_id)); GRANT SELECT,INSERT,UPDATE,DELETE ON public.facebook_pages TO authenticated; GRANT ALL ON public.facebook_pages TO service_role; ALTER TABLE public.facebook_pages ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users manage own pages" ON public.facebook_pages FOR ALL USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.messages_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,page_id text NOT NULL,sender_id text NOT NULL,sender_name text,direction text NOT NULL CHECK(direction IN('incoming','outgoing')),content text,media_type text,media_url text,ai_response text,status text NOT NULL DEFAULT 'ok',created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.messages_log TO authenticated; GRANT ALL ON public.messages_log TO service_role; ALTER TABLE public.messages_log ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users read own messages log" ON public.messages_log FOR SELECT USING(auth.uid()=user_id); CREATE INDEX messages_log_user_created_idx ON public.messages_log(user_id,created_at DESC);
CREATE TABLE public.comments_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,page_id text NOT NULL,post_id text NOT NULL,comment_id text NOT NULL UNIQUE,author_id text,author_name text,content text,replied boolean NOT NULL DEFAULT false,ai_response text,replied_at timestamptz,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.comments_log TO authenticated; GRANT ALL ON public.comments_log TO service_role; ALTER TABLE public.comments_log ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users read own comments log" ON public.comments_log FOR SELECT USING(auth.uid()=user_id); CREATE INDEX comments_log_user_created_idx ON public.comments_log(user_id,created_at DESC);
CREATE TABLE public.settings(user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,auto_reply_messages boolean NOT NULL DEFAULT true,auto_reply_comments boolean NOT NULL DEFAULT true,comment_scan_interval_minutes int NOT NULL DEFAULT 5,use_lovable_ai_fallback boolean NOT NULL DEFAULT true,default_model text NOT NULL DEFAULT 'gemini-2.5-flash',private_message_link text,facebook_app_id text,facebook_app_secret text,facebook_verify_token text,assistance_type text NOT NULL DEFAULT 'online_work' CHECK(assistance_type IN('online_work','training','sales')),global_ia_stopped boolean NOT NULL DEFAULT false,supabase_project_url text,supabase_project_name text,supabase_anon_key text,supabase_connected boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.settings TO authenticated; GRANT ALL ON public.settings TO service_role; ALTER TABLE public.settings ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users manage own settings" ON public.settings FOR ALL USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id); CREATE INDEX idx_settings_facebook_app_id ON public.settings(facebook_app_id) WHERE facebook_app_id IS NOT NULL; CREATE INDEX idx_settings_facebook_verify_token ON public.settings(facebook_verify_token) WHERE facebook_verify_token IS NOT NULL;
CREATE TABLE public.scheduled_posts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,page_id uuid REFERENCES public.facebook_pages(id) ON DELETE SET NULL,title text NOT NULL,image_path text,image_url text,ai_description text,scheduled_at timestamptz NOT NULL,frequency text NOT NULL DEFAULT 'once' CHECK(frequency IN('once','daily')),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','processing','published','failed','cancelled')),last_published_at timestamptz,last_error text,fb_post_id text,enhance_image boolean NOT NULL DEFAULT true,video_path text,ai_prompt text,image_paths text[] NOT NULL DEFAULT '{}',page_ids text[] NOT NULL DEFAULT '{}',media jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.scheduled_posts TO authenticated; GRANT ALL ON public.scheduled_posts TO service_role; ALTER TABLE public.scheduled_posts ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users manage own scheduled posts" ON public.scheduled_posts FOR ALL USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id); CREATE INDEX scheduled_posts_due_idx ON public.scheduled_posts(scheduled_at,status); CREATE INDEX scheduled_posts_user_created_idx ON public.scheduled_posts(user_id,created_at DESC);